ai.format:
Scena laboratorium fizyki 2D (moduł „Laboratorium fizyki”) — JSON. Silnik jest gotowy (ciała sztywne, zderzenia, tarcie, odbicia, przeguby, liny, pręty, sprężyny, bloczki, ciecze z ciśnieniem i wyporem); scena mówi tylko, CO w nim stoi.
Jednostki: metry, kilogramy, sekundy; y rośnie w górę, podłoże na y = 0. Każda liczba może być wyrażeniem "=…" z wartościami losowanymi w "vars" (np. "=4*tan(rad(kat))").

"world": { "gravity": 9.81, "air": 1 (opór powietrza, 0 — próżnia), "depth": 0.1 (grubość ciał — z niej masa), "ground": true, "speed": 1 }
"vars": [{ "name": "kat", "from": 15, "to": 40, "step": 5 }] albo { "name": "ciecz", "pick": ["water", "oil"] } — za każdym razem inne; w tekstach "{kat}"
"bodies": [{ "id", "label", "shape": "circle" (r) | "box" (w, h) | "poly" (points [[x,y],…], wypukły), "x", "y", "angle" (stopnie), "material", "density", "friction", "bounce", "static": true (nieruchome), "vx", "vy", "spin", "drag": false (nie da się chwycić), "trace": true (ślad), "color" }]
  materiały: {materials}
"joints": [{ "type": "pin" (oś obrotu w punkcie "at"; z "torque" i "speed" — silnik) | "rod" (pręt) | "rope" (lina) | "spring" (sprężyna: "k" N/m, "damping") | "pulley" (bloczek: "a", "b", koła w "at" i "at2"), "a": id, "b": id (pominięte — przyczepione do świata), "on": [x, y] (punkt na "a", względem jego środka), "at": [x, y] (punkt świata albo na "b"), "length" }]
"fluids": [{ "id", "x", "y" (lewy dolny róg wnętrza), "w", "h", "wall", "layers": [{ "liquid", "height" }] (od dołu; lżejsze same idą w górę), "holes": [{ "side": "left"|"right"|"bottom", "at" (wysokość nad dnem), "size", "open" }] }] — ciecze: {liquids}
"pipes": [{ "a", "b", "y", "size", "open" }] — rura łącząca dwa zbiorniki (naczynia połączone)
"show": { "vectors": [{vectors}] (v — prędkość, g — ciężar, lift — wypór, net — wypadkowa), "trace": [id], "grid", "pressure" (ciśnienie jako barwa głębi), "values" (masy, siły) }
"graph": { "body": id, "of": [{graph}] } — wykres w czasie (h wysokość, v prędkość, ek/ep/e energie)
"allow": { "add": false, "palette": [{palette}], "tools": [{tools}], "edit", "drag" }
"controls": [{controls}] — przełączniki świata w panelu
"goal": { "body": id, "area": [x0, y0, x1, y1], "for": 0.5, "say": "Udało się!" } — cel (np. piłka w koszu)
"steps": [{ "say": "…", "do": "play" | "pause" | { "open": idZbiornika, "hole": 0 } | { "push": id, "vx": 2, "vy": 0 }, "wait": 3 }] — kroki; „Pokaż” wykonuje je po kolei
"view": [x0, y0, x1, y1] — co widać na starcie
